```instr
instrument tof_imaging_beamline {
    // Instrument parameters
    parameter double lam = 3.5;
    parameter double dlam = 1.3;
    parameter double ap_D = 0.016;

    // Source
    Source_simple src(
        yheight = 0.12,
        xwidth = 0.1,
        dist = 1.0,
        focus_xw = ap_D,
        focus_yh = ap_D,
        lambda0 = lam,
        dlambda = dlam,
        flux = 10000000000000.0
    ) AT (0, 0, 0) RELATIVE ABSOLUTE;

    // Aperture
    Slit aperture(
        radius = 0.5 * ap_D
    ) AT (0, 0, 1.0) RELATIVE src;

    // Scraper
    Slit scraper(
        xwidth = 0.3,
        yheight = 0.3
    ) AT (0, 0, 10.0) RELATIVE src;

    // Field of view monitor
    PSD_monitor fov_mon(
        nx = 128,
        ny = 128,
        filename = "fov.dat",
        xwidth = 0.28,
        yheight = 0.28,
        restore_neutron = 1
    ) AT (0, 0, 20.0) RELATIVE src;

    // Detector monitor
    PSD_monitor det(
        nx = 256,
        ny = 256,
        filename = "det.dat",
        xwidth = 0.2,
        yheight = 0.2,
        restore_neutron = 1
    ) AT (0, 0, 25.0) RELATIVE src;

    // Wavelength monitor at detector position
    L_monitor det_lam(
        nL = 200,
        filename = "det_lam.dat",
        xwidth = 0.2,
        yheight = 0.2,
        Lmin = lam - 2 * dlam,
        Lmax = lam + 2 * dlam,
        restore_neutron = 1
    ) AT (0, 0, 25.01) RELATIVE src;

    // Define the neutron path
    neutron_path {
        src -> aperture -> scraper -> fov_mon -> det -> det_lam;
    }

    // Set simulation parameters
    set_seed(123456);  // Fixed seed for reproducibility
    set_ncount(1e6);   // Sufficient for initial verification
}
```

